import{_ as d,o as a,c as n,a2 as l,j as e,a as t,t as r}from"./chunks/framework.CCXDMzJr.js";const b=JSON.parse('{"title":"第 13 章 提示词组装与作用域","description":"","frontmatter":{},"headers":[],"relativePath":"ch13-system-prompt-scope.md","filePath":"ch13-system-prompt-scope.md","lastUpdated":1786693096000}'),c={name:"ch13-system-prompt-scope.md"},i={tabindex:"0"};function p(s,o,u,m,g,h){return a(),n("div",null,[o[13]||(o[13]=l('<h1 id="第-13-章-提示词组装与作用域" tabindex="-1">第 13 章 提示词组装与作用域 <a class="header-anchor" href="#第-13-章-提示词组装与作用域" aria-label="Permalink to &quot;第 13 章 提示词组装与作用域&quot;">​</a></h1><p>本章覆盖两个紧密配合的包：<code>core/scope</code>（每代理作用域注册原语，库无服务）与 <code>core/system-prompt</code>（提示词分节与工具 schema 组装，<code>ctx.systemPrompt</code>）。</p><h2 id="_13-1-scope-作用域原语" tabindex="-1">13.1 scope：作用域原语 <a class="header-anchor" href="#_13-1-scope-作用域原语" aria-label="Permalink to &quot;13.1 scope：作用域原语&quot;">​</a></h2><p><code>packages/core/scope</code>（约 560 行）<strong>没有注册任何 Cordis 服务</strong>——它是一组被 session/system-prompt/tools 共同消费的纯库原语（依赖链最底层）。</p><h3 id="核心抽象" tabindex="-1">核心抽象 <a class="header-anchor" href="#核心抽象" aria-label="Permalink to &quot;核心抽象&quot;">​</a></h3><ul><li><strong><code>ScopeKey</code></strong>：一个不透明对象身份（惰性、不检视内容）。默认实现直接用活 <code>Agent</code> 对象本身作为 key；</li><li><strong><code>Scoped&lt;T&gt;</code></strong>：仅编译期品牌——事件声明 <code>&#39;agent/created&#39;(this: Scoped&lt;Agent&gt;, ...)</code> 意味着&quot;携带 agent 载体、按作用域过滤派发&quot;；</li><li><strong><code>Scope</code> / <code>ScopeLayer</code></strong>：一个作用域的上下文（<code>ctx</code>）+ 释放（<code>rawDispose</code> 保留 Cordis 确切 disposer 身份供有序组合；<code>dispose()</code> 是共享静默边界）；</li><li><strong><code>ScopedLayers&lt;L&gt;</code></strong>：eager global 层 + 惰性 exact-scope 层。<strong>读不建层</strong>；注册（<code>effect</code>）同时决定&quot;可见性 + effect 归属&quot;，收集同步 undo，整层空时回收 scoped 层；</li><li><strong><code>NamedEntries</code> / <code>AnonymousEntries</code></strong>：有序条目表；Named 带重名诊断（同层重名报错），Anonymous 每项独立身份；返回幂等逐项 undo。</li></ul><h3 id="两个相反的传播方向" tabindex="-1">两个相反的传播方向 <a class="header-anchor" href="#两个相反的传播方向" aria-label="Permalink to &quot;两个相反的传播方向&quot;">​</a></h3><p><code>ScopedLayers</code> 的注释点出一个精妙设计（<code>index.ts:32-39</code>）：<strong>一个 <code>scopeParents</code> 关系同时驱动两个方向</strong>——</p><ol><li><strong>注册视图向下继承</strong>：子作用域可见其祖先作用域层（<code>chainLayers</code>）——agent 作用域能看到全局层的注册；</li><li><strong>事件接受向上延伸</strong>：带祖先标签的监听者能收到发往任意后代键的事件（<code>scopeTarget</code> 的 filter）——全局监听者收到所有 agent 的事件，agent 专属监听者只收自己的。</li></ol><p>这是&quot;全局工具 + 每 agent 工具&quot;、&quot;全局事件 + 每 agent 事件&quot;能共存于同一套注册表的机制。</p><h2 id="_13-2-system-prompt-组装与排序" tabindex="-1">13.2 system-prompt：组装与排序 <a class="header-anchor" href="#_13-2-system-prompt-组装与排序" aria-label="Permalink to &quot;13.2 system-prompt：组装与排序&quot;">​</a></h2>',11)),e("p",null,[o[2]||(o[2]=e("code",null,"packages/core/system-prompt",-1)),o[3]||(o[3]=t("（约 600 行）注册 ",-1)),o[4]||(o[4]=e("code",null,"ctx.systemPrompt",-1)),o[5]||(o[5]=t(" 服务，职责：",-1)),e("strong",null,[o[0]||(o[0]=t("注册有序 system 节、动态上下文、工具 schema providers 与 ",-1)),e("code",null,r(s.variable),1),o[1]||(o[1]=t("，在每次模型步前按角色组装、排序、渲染成完整提示词",-1))]),o[6]||(o[6]=t("。",-1))]),o[14]||(o[14]=e("h3",{id:"注册面",tabindex:"-1"},[t("注册面 "),e("a",{class:"header-anchor",href:"#注册面","aria-label":'Permalink to "注册面"'},"​")],-1)),e("table",i,[o[12]||(o[12]=e("thead",null,[e("tr",null,[e("th",null,"抽象"),e("th",null,"语义")])],-1)),e("tbody",null,[o[9]||(o[9]=e("tr",null,[e("td",null,[e("code",null,"PromptSection { name, order, text, complete? }")]),e("td",null,[t("system 节。"),e("code",null,"order"),t(" 决定拼接顺序；"),e("code",null,"complete: true"),t(' 的节是"整段提示"——多于一个有效 complete 节会使组装失败；waterfall 之后恢复该节为唯一节')])],-1)),o[10]||(o[10]=e("tr",null,[e("td",null,[e("code",null,"PromptContext { name, order, text }")]),e("td",null,[t("动态上下文，物化为"),e("strong",null,"持久 user-role 快照"),t("（这就是 "),e("code",null,"agent.inject()"),t(" 提示词侧的表达）")])],-1)),o[11]||(o[11]=e("tr",null,[e("td",null,"工具 providers"),e("td",null,[e("code",null,"systemPrompt.tools(...)"),t("——"),e("code",null,"SessionStore"),t(" 与 "),e("code",null,"ToolRuntime"),t(" 构造时向它登记工具 provider，组装时产出模型可见的工具 schema 列表")])],-1)),e("tr",null,[o[8]||(o[8]=e("td",null,"变量",-1)),e("td",null,[e("code",null,r(s.variable),1),o[7]||(o[7]=t(" 渲染",-1))])])])]),o[15]||(o[15]=l('<p><code>assemble(context)</code> 输出<strong>可合并扩展</strong>的 <code>PromptAssembly { sections, contexts, tools, variables }</code>，然后跑 <code>system-prompt/assemble</code> <strong>waterfall</strong>——专家监听者可以改写组装结果（<code>complete</code> 节除外）。</p><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>模式</th><th>语义</th></tr></thead><tbody><tr><td><code>system-prompt/assemble</code></td><td>waterfall</td><td>改写组装结果（每次模型步前）</td></tr><tr><td><code>system-prompt/change</code></td><td>emit</td><td>注册面变化（节/工具/变量增删）</td></tr></tbody></table><p>第 1 章提到的&quot;harness source 提示词节&quot;（<code>addHarnessSourceSection</code>，<code>app-boot/index.ts:821-829</code>）就是一个 <code>systemPrompt.section({ name, order: -99, text })</code> 调用——引导 Agent 知道 harness checkout 在哪。</p><h2 id="_13-3-组装如何发生" tabindex="-1">13.3 组装如何发生 <a class="header-anchor" href="#_13-3-组装如何发生" aria-label="Permalink to &quot;13.3 组装如何发生&quot;">​</a></h2><p>每次模型步前，循环调用 <code>ctx.systemPrompt.assemble(...)</code>：</p><ol><li>按作用域收集：全局层 + 该 agent 的 exact 层（节、上下文、工具 provider）；</li><li>按 <code>order</code> 排序节，拼接文本；</li><li>渲染变量、物化动态上下文；</li><li>收集工具 schema（注册的工具自动可见）；</li><li>派发 <code>system-prompt/assemble</code> waterfall（可改写）；</li><li>结果进入 <code>EpochHeader.system</code>，随 <code>request/header</code> 事件<strong>写入会话日志</strong>——保证&quot;请求信封可重建&quot;。</li></ol><h2 id="_13-4-作用域如何让-每-agent-能力集-成立" tabindex="-1">13.4 作用域如何让&quot;每 agent 能力集&quot;成立 <a class="header-anchor" href="#_13-4-作用域如何让-每-agent-能力集-成立" aria-label="Permalink to &quot;13.4 作用域如何让&quot;每 agent 能力集&quot;成立&quot;">​</a></h2><p>把三块拼起来：</p><ul><li><strong>agent 创建时</strong>：<code>setup(agentCtx)</code> 在 agent 的 scope context 上装载 preset 插件（第 16 章）；</li><li>preset 插件注册的工具/提示词节/事件监听器都落在 <code>agentCtx</code> 的 scope 层；</li><li>该 agent 的循环在 <code>agentCtx</code> 内运行 → <code>assemble</code> 只看到本 agent 的层 + 全局层；</li><li>agent 销毁 → scope 回卷 → 注册全部撤销。</li></ul><p>于是&quot;每个会话拥有不同能力集&quot;（如不同 preset 给不同工具）不需要任何全局状态——只是作用域层的叠加与回收。</p><h2 id="_13-5-小结" tabindex="-1">13.5 小结 <a class="header-anchor" href="#_13-5-小结" aria-label="Permalink to &quot;13.5 小结&quot;">​</a></h2><ul><li>scope 是纯库原语：ScopeKey/Scoped/ScopedLayers，一个 parent 关系同时驱动&quot;注册向下继承&quot;与&quot;事件向上延伸&quot;；</li><li>system-prompt 注册有序节/上下文/工具 providers/变量，每次模型步前组装 + waterfall 可改写；</li><li>组装结果进入日志（request/header），保证可重建；</li><li>作用域层让每 agent 能力集自然成立，销毁即回卷。</li></ul><p>下一章：LLM 适配器接缝。</p>',14))])}const y=d(c,[["render",p]]);export{b as __pageData,y as default};
